import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

const read = path => JSON.parse(readFileSync(new URL("../"+path,import.meta.url),"utf8"));
const ledger=read("data/geography/research/sacred-atlas-chat-photo-decisions-round1-20261031.v1.json");
const review=read("data/geography/research/sacred-atlas-round1-commons-rights-triage-20261031.v1.json");
const registry=read("data/geography/seed-registry.v1.json");
const sites=new Set(registry.places.map(x=>x.place_id));

assert.equal(ledger.batch,1);
assert.equal(review.schema,"AO_SACRED_ATLAS_ROUND1_COMMONS_RIGHTS_TRIAGE_V1");
assert.equal(review.scope,"RESEARCH_ONLY_RIGHTS_AND_IDENTITY_TRIAGE_NO_MEDIA_PUBLICATION");
assert.equal(review.totals.total,20);
assert.equal(review.files.length,ledger.decisions.length);
assert.equal(review.totals.contemporary_sourced_photo_pages,18);
assert.equal(review.totals.archive_postcards,1);
assert.equal(review.totals.wrong_site,1);
assert.equal(review.totals.confirmed_unchanged_user_keeps,20);
assert.equal(review.totals.publication_ready,0);
const commonsTitle=new Set();
for(let i=0;i<review.files.length;i++){
 const file=review.files[i], approved=ledger.decisions[i];
 assert.equal(file.number,i+1);
 assert.equal(approved.number,file.number);
 assert.equal(approved.place_id,file.place_id);
 assert.equal(approved.subject_id,file.subject_id);
 assert(sites.has(file.place_id));
 assert.equal(approved.decision,"KEEP");
 assert.equal(file.user_decision,"KEEP_UNCHANGED");
 assert(file.source_file_title.startsWith("File:"));
 assert(!commonsTitle.has(file.source_file_title));
 commonsTitle.add(file.source_file_title);
 assert(file.source_file_page.startsWith("https://commons.wikimedia.org/wiki/File:"));
 assert(file.photographer_or_source_credit.length>1);
 assert(file.commons_stated_license.length>4);
 assert(file.dimensions_claimed_pixels.width>=300);
 assert(file.dimensions_claimed_pixels.height>=300);
 assert.equal(file.commons_photo_license_source_checked,true);
 assert.equal(file.on_screen_preview_pixel_match_verified,false);
 assert.equal(file.identity_verified,false);
 assert.equal(file.original_file_bytes_fetched,false);
 assert.equal(file.original_file_sha256,null);
 assert.equal(file.artwork_rights_cleared,false);
 assert.equal(file.photographer_license_compliance_ready,false);
 assert.equal(file.publishable,false);
 assert.equal(file.published,false);
 assert.equal(approved.published,false);
 assert(file.legal_hold.length>=15);
 assert(file.provenance_risk.includes("dynamically retrieved image preview"));
}
const f=n=>review.files[n-1];
assert.equal(f(19).exact_subject_and_place_status,"HISTORICAL_REFERENCE_NOT_CONTEMPORARY_PHOTO");
assert.match(f(19).notes,/postcard/i);
assert.equal(f(20).exact_subject_and_place_status,"WRONG_SITE_LA_RABATELIERE_NOT_LA_SALETTE");
assert.match(f(20).notes,/La Rabatelière/);
assert.equal(f(20).commons_stated_license,"CC0 1.0");
assert(f(20).legal_hold.includes("DO_NOT_PUBLISH"));
const replacements=review.alternative_candidates;
assert(replacements.some(x=>x.for_round1_number===20&&x.status==="VALID_SITE_ALTERNATIVE_UNAPPROVED"&&!x.publication_approved));
assert(replacements.some(x=>x.for_round1_number===19&&x.status==="REJECT_ALTERNATIVE_WRONG_SUBSITE"));
assert(replacements.some(x=>x.for_round1_number===5&&x.status==="OFFICIAL_GALLERY_LICENSE_REQUIRED_DO_NOT_DOWNLOAD"));
console.log("Sacred Atlas source and rights triage: 20 KEEP preserved, 18 current-photo pages, 1 archival postcard, 1 wrong site, 0 publication promotions — PASS");
